        _write_jsonl(fake_projects / "sess.jsonl", [
            _hook_deny_current("Commit blocked by code-review gate: run /code-review.", tool_id="b1"),
            _hook_deny_current("Blocked by code-review gate: could not source _lib.sh.", tool_id="b2"),
        ])
