        sub_tool_result = _user_msg([_tool_result("sub-tool-1", "ok")], ts="2026-08-01T10:00:10.000Z")
        main_tool_result = _user_msg([_tool_result("main-tool-1", "ok")], ts="2026-08-01T10:05:55.000Z")
